    getDataByLocationFor1206: function(repoYear) {
        var strQuery = "initial_review.location_controlled_by_employer=Yes^initial_review.occurrence_buildingISNOTEMPTY";
        strQuery = strQuery + "^hr_service=" + this.HCVTypeID;

        var strQueryYear = "^sys_created_on>=" + repoYear + "-01-01^sys_created_on<=" + repoYear + "-12-31";
        var gr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
        gr.addEncodedQuery(strQuery);
        gr.addEncodedQuery(strQueryYear);

        gr.query();
        var buildingCounts = [];
        var total = 0;
        //var buildings = [];
        while (gr.next()) {
            total = total + 1;
            var building = gr.initial_review.occurrence_building.sys_id.toString();
            //if (buildings.indexOf(building) < 0) {
            //	buildings.push(building);
            //}
            var curBuilding = buildingCounts.find(x => x.sys_id == building);
            if (!curBuilding) {
                buildingCounts.push({
                    count: 1,
                    street: gr.initial_review.occurrence_building.street.toString(),
                    city: gr.initial_review.occurrence_building.city.toString(),
                    province: gr.initial_review.occurrence_building.state.toString(),
                    postal: gr.initial_review.occurrence_building.zip.toString(),
                    name: gr.initial_review.occurrence_building.name.toString(),
                    sys_id: building,
                    address: gr.initial_review.occurrence_building.street.toString() +
                        ", " + gr.initial_review.occurrence_building.city.toString() +
                        ", " + gr.initial_review.occurrence_building.state.toString() +
                        ", " + gr.initial_review.occurrence_building.zip.toString()
                })
            } else {
                curBuilding.count = curBuilding.count + 1;
            }
        }
        return {
            locations: buildingCounts,
            total: total
        };

    },
